import axios from 'axios';

const api = axios.create({
  baseURL: '/api',  // Путь для API через proxy
});

// Пример кэширования данных в localStorage
const fetchMatches = async () => {
  const cachedMatches = localStorage.getItem('matches');

  // Если данные есть в localStorage — возвращаем их
  if (cachedMatches) {
    console.log('Данные получены из localStorage');
    return JSON.parse(cachedMatches);
  }

  // Если данных нет в localStorage — делаем запрос к API
  try {
    const response = await api.get('/matches/live');

    // Сохраняем полученные данные в localStorage
    localStorage.setItem('matches', JSON.stringify(response.data));

    console.log('Данные получены с API и сохранены в localStorage');
    return response.data;
  } catch (error) {
    console.error('Ошибка при запросе live матчей:', error);
    // Обработка ошибки (можно вернуть старые кэшированные данные или пустой массив)
    return [];
  }
};

export { fetchMatches };
